import{_ as s,o as a,c as t,a6 as n}from"./chunks/framework.DtfPIzdJ.js";const u=JSON.parse('{"title":"1. Create the project","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/01-setup.md","filePath":"tutorial/01-setup.md"}'),i={name:"tutorial/01-setup.md"};function o(p,e,l,r,c,d){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_1-create-the-project" tabindex="-1">1. Create the project <a class="header-anchor" href="#_1-create-the-project" aria-label="Permalink to &quot;1. Create the project&quot;">​</a></h1><p><strong>Goal:</strong> create the Helpdesk project, run it in the browser, change the first page, and meet the compiler.</p><h2 id="create-the-project" tabindex="-1">Create the project <a class="header-anchor" href="#create-the-project" aria-label="Permalink to &quot;Create the project&quot;">​</a></h2><p>Open a terminal in the folder where you keep your projects and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpdesk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blank</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ Created helpdesk from the blank template.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  cd helpdesk</span></span>
<span class="line"><span>  cluub dev</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then open http://localhost:3000. Edit any .clb file and the page reloads.</span></span></code></pre></div><p>There are three templates. <code>app</code> (the default) is a finished todo app and <code>ai-chat</code> is a chat assistant. We use <code>blank</code> because we want to build everything ourselves. It gives you the folder structure and one page. See <a href="/home/guide/install">Install &amp; first app</a> for the others.</p><h2 id="look-around" tabindex="-1">Look around <a class="header-anchor" href="#look-around" aria-label="Permalink to &quot;Look around&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpdesk</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>helpdesk/</span></span>
<span class="line"><span>├── .env.example        # where AI keys will go (chapter 6)</span></span>
<span class="line"><span>├── .gitignore          # ignores dist/, storage/ and .env</span></span>
<span class="line"><span>├── app.clb             # the app&#39;s name and settings</span></span>
<span class="line"><span>├── models/             # data shapes and their rules</span></span>
<span class="line"><span>├── data/               # stores: where models are saved</span></span>
<span class="line"><span>├── network/            # clients for outside APIs</span></span>
<span class="line"><span>├── services/           # business logic and AI</span></span>
<span class="line"><span>├── api/                # HTTP endpoints</span></span>
<span class="line"><span>├── ui/</span></span>
<span class="line"><span>│   ├── pages/</span></span>
<span class="line"><span>│   │   └── home.clb    # the only page so far</span></span>
<span class="line"><span>│   ├── components/</span></span>
<span class="line"><span>│   └── layouts/</span></span>
<span class="line"><span>└── tests/</span></span></code></pre></div><p>(The empty folders hold a <code>.keep</code> file so they exist. You can ignore those.)</p><p>Every Cluub project has <strong>exactly this shape</strong>, and the compiler enforces it. A model must live in <code>models/</code>, a page in <code>ui/pages/</code>, and so on. Put one in the wrong place and you get error <strong>E301</strong> with the folder it belongs in. This sounds strict, but it means that anyone, whether a teammate, a reviewer or an AI assistant, can open any Cluub project and know where everything is. <a href="/home/guide/structure">Project structure &amp; layers</a> explains the reasoning.</p><p>Open <code>app.clb</code>:</p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">app</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Helpdesk</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span></code></pre></div><p>This is the <a href="/home/reference/app"><code>app</code> declaration</a>. Cluub turned the folder name <code>helpdesk</code> into the app name <code>Helpdesk</code>. Two things to notice about the syntax:</p><ul><li>A <strong>declaration</strong> starts at the beginning of a line with a keyword (<code>app</code>, <code>model</code>, <code>page</code>, ...) and a name. Declaration names are <code>PascalCase</code>.</li><li>Everything that belongs to it is <strong>indented by two spaces</strong>. There are no braces and no semicolons. Indentation is the structure.</li></ul><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><p>Start the development server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ Started in 1.8ms (1 pages · 0 apis · 0 services · 0 models)</span></span>
<span class="line"><span>  http://localhost:3000  · watching for changes · Ctrl+C to stop</span></span></code></pre></div><p>Open <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>. You see a heading &quot;Hello from Helpdesk&quot; and a line telling you to edit <code>ui/pages/home.clb</code>.</p><p><code>cluub dev</code> compiles the whole project (frontend and backend), starts one server for both, and <strong>watches your files</strong>. Every time you save a <code>.clb</code> file it recompiles and reloads the browser. Leave it running in its own terminal tab for the rest of the tutorial. If port 3000 is busy, use <code>cluub dev --port 3001</code>.</p><h2 id="your-first-page" tabindex="-1">Your first page <a class="header-anchor" href="#your-first-page" aria-label="Permalink to &quot;Your first page&quot;">​</a></h2><p>Open <code>ui/pages/home.clb</code> and replace its contents:</p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">page</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Home</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  about</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;The front door of the helpdesk&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Helpdesk&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  view</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    heading</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Helpdesk&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    text</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Customers will send us support tickets from this page.&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    text</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Agents will work through them in the queue.&quot;</span></span></code></pre></div><p>Save. The browser reloads by itself.</p><p>Line by line:</p><ul><li><code>page Home at &quot;/&quot;</code> declares a <a href="/home/reference/page">page</a> called <code>Home</code> that lives at the URL <code>/</code>.</li><li><code>about &quot;...&quot;</code> is a one-line description for humans. Cluub uses <code>about</code> lines to write documentation for your product owner and QA team (chapter 8), and suggests adding one when it&#39;s missing (suggestion W104).</li><li><code>title &quot;Helpdesk&quot;</code> sets the browser tab title.</li><li><code>view</code> is what the page shows. Each line inside it is a <a href="/home/reference/view-elements">view element</a>: <code>heading</code> becomes a big title, <code>text</code> a paragraph. Indentation nests them, just like the rest of the language.</li></ul><p>There is no HTML, no JSX and no CSS here. Cluub has a built-in theme that looks clean on desktop and mobile and supports dark mode. You can change it later with a <code>theme.css</code> file (see <a href="/home/guide/frontend#look-and-feel">Pages &amp; components</a>).</p><h2 id="meet-the-compiler" tabindex="-1">Meet the compiler <a class="header-anchor" href="#meet-the-compiler" aria-label="Permalink to &quot;Meet the compiler&quot;">​</a></h2><p>Mistakes happen, so let&#39;s make one on purpose. In <code>ui/pages/home.clb</code>, misspell <code>heading</code> as <code>heding</code> and save. The terminal running <code>cluub dev</code> shows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error E013 ui/pages/home.clb:5:5</span></span>
<span class="line"><span>  \`heding\` is not a view element.</span></span>
<span class="line"><span>   4 |   view</span></span>
<span class="line"><span>   5 |     heding &quot;Helpdesk&quot;</span></span>
<span class="line"><span>     |     ^^^^^^</span></span>
<span class="line"><span>  hint: Did you mean \`heading\`?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✗ 1 error · 0 warnings · 0 suggestions</span></span></code></pre></div><p>Every Cluub error has the same shape: a <strong>code</strong> (<code>E013</code>, look any of them up with <code>cluub errors E013</code> or in <a href="/home/reference/errors">Error codes</a>), the <strong>file, line and column</strong>, the offending code with a marker under it, and a <strong>hint</strong> that usually tells you the fix. While there&#39;s an error, <code>cluub dev</code> keeps serving the last good version and waits for you.</p><p>Fix the typo, save, and the page is back.</p><p>You can get the same report without running the server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ No errors (0 suggestions · checked in 1.9ms)</span></span></code></pre></div><p><code>cluub check</code> is fast enough to run on every save, in a pre-commit hook or in CI.</p><h2 id="your-first-test-run" tabindex="-1">Your first test run <a class="header-anchor" href="#your-first-test-run" aria-label="Permalink to &quot;Your first test run&quot;">​</a></h2><p>You haven&#39;t written a test yet, but Cluub has already written one for you:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generated 1 test in tests/generated/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tests/generated/ui.test.clb</span></span>
<span class="line"><span>  ✓ Home page: renders 1ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 passed in 2ms</span></span></code></pre></div><p>Open <code>tests/generated/ui.test.clb</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>test &quot;Home page: renders&quot;</span></span>
<span class="line"><span>  render Home</span></span>
<span class="line"><span>  expect screen has &quot;Helpdesk&quot;</span></span>
<span class="line"><span>  expect screen has &quot;Customers will send us support tickets from this page.&quot;</span></span></code></pre></div><p>Every time you run <code>cluub test</code>, Cluub reads your code and writes tests for it: one for each model rule, each <code>require</code> in a service, each api route, each page and each button. It runs them together with the tests you write yourself, in one process, with a fresh in-memory database and no network. You&#39;ll see this list grow in every chapter, and in <a href="/home/tutorial/07-testing">chapter 7</a> you&#39;ll write your own. Don&#39;t edit files in <code>tests/generated/</code>. They are rewritten on every run.</p><h2 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h2><p>You should now have:</p><ul><li>A <code>helpdesk/</code> folder with the structure shown above.</li><li><code>cluub dev</code> running, and <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a> showing the heading <strong>Helpdesk</strong> and two lines of text. The browser tab is titled &quot;Helpdesk&quot;.</li><li><code>cluub check</code> printing <code>✓ No errors</code>.</li><li><code>cluub test</code> printing <code>1 passed</code>.</li></ul><h2 id="recap" tabindex="-1">Recap <a class="header-anchor" href="#recap" aria-label="Permalink to &quot;Recap&quot;">​</a></h2><ul><li><code>cluub new &lt;name&gt; --template blank</code> creates a project with the standard folder layout. The compiler enforces that layout.</li><li><code>cluub dev</code> compiles, serves and live-reloads the whole app.</li><li>Declarations start at column 1 with a keyword and a <code>PascalCase</code> name; their contents are indented by two spaces.</li><li>A <code>page</code> has a URL, an <code>about</code>, a <code>title</code> and a <code>view</code> made of elements like <code>heading</code> and <code>text</code>.</li><li>Errors have a code, a location and a hint. <code>cluub check</code> shows them without running anything.</li><li><code>cluub test</code> writes tests for your code and runs them.</li></ul><p>Next: <a href="/home/tutorial/02-ticket-model">2. The Ticket model</a>, where we describe what a ticket is.</p>`,51)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
